options=read('/input/options')
from itertools import combinations
result=[]
for k in range(goal['min_count'],goal['max_count']+1):
 for combo in combinations(options,k):
  ids=[o['id'] for o in combo]
  # Check requires closure
  all_requires=True
  for o in combo:
   for r in o['requires']:
    if r not in ids:
     all_requires=False
     break
   if not all_requires:
    break
  if not all_requires:
   continue
  # Check conflicts
  if goal['no_conflicts']:
   conflict_found=False
   for o in combo:
    for c in o['conflicts']:
     if c in ids:
      conflict_found=True
      break
    if conflict_found:
     break
   if conflict_found:
    continue
  # Check cover tags
  tags_covered=[]
  for o in combo:
   tags_covered+=o['tags']
  tags_covered_set=list(set(tags_covered))
  cover_tags=goal['cover'].get('tags',[])
  cover_ok=True
  for t in cover_tags:
   if t not in tags_covered_set:
    cover_ok=False
    break
  if not cover_ok:
   continue
  # Check sum_bounds cost max
  cost_sum=sum(o['cost'] for o in combo)
  if 'cost' in goal['sum_bounds']:
   if 'max' in goal['sum_bounds']['cost']:
    if cost_sum>goal['sum_bounds']['cost']['max']:
     continue
   if 'min' in goal['sum_bounds']['cost']:
    if cost_sum<goal['sum_bounds']['cost']['min']:
     continue
  # Check unique fields
  unique_fields=goal.get('unique',[])
  unique_ok=True
  for f in unique_fields:
   vals=[o.get(f) for o in combo]
   if len(vals)!=len(list(set(vals))):
    unique_ok=False
    break
  if not unique_ok:
   continue
  # Check order_by ascending lex
  order_by=goal.get('order_by',[])
  if order_by:
   sorted_combo=sorted(combo,key=lambda x: tuple(x.get(f) for f in order_by))
   if list(sorted_combo)!=list(combo):
    continue
  # If all checks passed
  result=ids
  break
 if result:
  break

