   for o in combo:
    for r in o['requires']:
     if r not in ids:
      all_requires=False
      break
    if not all_requires:
     break
   if not all_requires:
    continue
  # Check conflicts if no_conflicts
  if no_conflicts:
   conflict_found=False
   for o in combo:
    for c in o['conflicts']:
     if c in ids:
      conflict_found=True
      break
    if conflict_found:
     break
   if conflict_found:
    continue
  # Check cover tags
  tags_covered=[]
